// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;

    function setUp() public {
        c = new MY_BANK(address(new Log()));
    }

    function testFuzz_property(uint256 amount, uint256 unlockTime, address actor) public {
        // Keep actor a non-zero, non-precompile address, and keep amounts in a wide but non-extreme range
        vm.assume(actor != address(0));
        bound(amount, 0, 1 ether);
        bound(unlockTime, 0, block.timestamp + 365 days);

        // Seed the actor with exactly some balance below MinSum
        uint256 seed = bound(amount, 0, c.MinSum() > 0 ? c.MinSum() - 1 : 0);
        vm.deal(actor, seed);

        // Put the seed through the fallback/Put to set Acc[actor].balance = seed
        vm.prank(actor);
        (bool okPut, ) = address(c).call{value: seed}("");
        okPut;

        // Warp past the unlock time so Collect can succeed if the balance threshold allows it
        vm.warp(__invmut_c_Acc_unlockTime(actor) + 1);

        // Attempt to collect an amount that would need to be no more than the seed
        uint256 collectAmount = bound(amount, 0, seed);
        vm.prank(actor);
        bool okCollect; try c.Collect{value: 0}(collectAmount) { okCollect = true; } catch { okCollect = false; }
        okCollect;

        // General rule over ALL accounts: no account with balance below MinSum can have its balance reduced by Collect
        // Since the seed is always below MinSum in the buggy case, the buggy Collect succeeds and reduces the balance.
        // The reference cannot reduce a below-MinSum balance, so balance stays the same.
        uint256 expectedBalance = seed;
        if (seed >= c.MinSum()) {
            // If seed was at least MinSum, Collect would reduce by collectAmount, but seed is bounded below MinSum
            expectedBalance = seed - collectAmount;
        }

        assertTrue(__invmut_c_Acc_balance(actor) == expectedBalance || __invmut_c_Acc_balance(actor) >= c.MinSum());
    }

    function __invmut_c_Acc_balance(address __k) internal view returns (uint256) {
        (, uint256 _v1) = c.Acc(__k);
        return _v1;
    }
    function __invmut_c_Acc_unlockTime(address __k) internal view returns (uint256) {
        (uint256 _v0, ) = c.Acc(__k);
        return _v0;
    }
}
